"""Apple Object Capture bridge. Geometry is generated by RealityKit, never mocked."""
import json
import os
from pathlib import Path
import platform
import subprocess
import threading
import time
from .pipeline import write_status

PROJECT = Path(__file__).resolve().parent.parent
EXECUTABLE = PROJECT / '.tools' / 'imersity-object-capture'
ACTIVE = set()
ACTIVE_LOCK = threading.Lock()
DETAIL_PROFILES = ('preview', 'reduced', 'medium', 'full', 'custom', 'head-custom')

def validate_options(detail, base_cut):
    if detail not in DETAIL_PROFILES:
        raise ValueError('Nível de detalhe inválido.')
    if not 0 <= base_cut <= .70:
        raise ValueError('O recorte da base deve ficar entre 0% e 70%.')
    if detail != 'head-custom' and base_cut != .30:
        raise ValueError('Recorte disponível somente no teste concentrado na cabeça.')

def stop_all():
    with ACTIVE_LOCK:
        for process in list(ACTIVE):
            if process.poll() is None: process.terminate()

STAGES = {'preProcessing': 'Preparando imagens', 'imageAlignment': 'Alinhando câmeras', 'pointCloudGeneration': 'Gerando nuvem de pontos', 'meshGeneration': 'Construindo a malha', 'textureMapping': 'Aplicando texturas', 'optimization': 'Otimizando modelo', 'inputComplete': 'Imagens carregadas', 'headReconstruction': 'Reconstruindo o volume recortado'}

def requirements():
    result = {'ready': False, 'missing': [], 'pipeline': 'apple-object-capture', 'device': 'Apple Silicon / Metal', 'resultName': 'head.usdz', 'detailProfiles': DETAIL_PROFILES, 'savedCaptures': True}
    if platform.system() != 'Darwin':
        result['missing'] = ['macOS com suporte a Object Capture']; return result
    if not EXECUTABLE.is_file():
        result['missing'] = ['Executável nativo ausente. Inicie pelo arquivo Iniciar Imersity.command.']; return result
    try:
        check = subprocess.run([str(EXECUTABLE), '--check'], capture_output=True, text=True, timeout=20, check=True)
        support = json.loads(check.stdout.strip().splitlines()[-1])
        result.update(support)
        result['ready'] = bool(support.get('supported'))
        result['device'] = support.get('metalDevice', result['device'])
        if not result['ready']:
            result['missing'] = ['Object Capture não está disponível neste processo. Abra Iniciar Imersity.command no Terminal do macOS e verifique novamente.']
    except (OSError, ValueError, subprocess.SubprocessError) as error:
        result['missing'] = [f'Falha no diagnóstico nativo: {error}']
    return result

def run_job(directory: Path, detail='reduced', base_cut=.30):
    started = time.time()
    process = None
    timer = None
    try:
        write_status(directory, status='processing', stage='preflight', progress=0)
        check = requirements()
        if not check['ready']:
            raise RuntimeError('; '.join(check['missing']))
        validate_options(detail, base_cut)
        destination = directory / 'result' / 'head.usdz'
        destination.parent.mkdir(parents=True, exist_ok=True)
        command = [str(EXECUTABLE), str(directory / 'capture' / 'train'), str(destination), detail]
        if detail == 'head-custom': command.append(str(base_cut))
        with (directory / 'pipeline.log').open('a', buffering=1) as log:
            log.write('Object Capture local. Imagens de avaliação excluídas. Escala sem validação métrica.\n')
            log.write('Máscara automática desativada: o modelo pode incluir ombros e fundo.\n')
            if detail in ('custom', 'head-custom'):
                log.write('Experimento: limite de 500.000 polígonos, mapas de até 8K. Sem subdivisão artificial.\n')
            if detail == 'head-custom':
                log.write(f'Recorte: excluir {base_cut:.0%} da base no eixo Y. Supõe pessoa em pé no volume; não detecta cabeça automaticamente.\n')
            process = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, bufsize=1)
            with ACTIVE_LOCK: ACTIVE.add(process)
            timed_out = threading.Event()
            def stop_timeout():
                timed_out.set(); process.kill()
            timer = threading.Timer(2 * 60 * 60, stop_timeout)
            timer.daemon = True; timer.start()
            native_error = None
            for line in process.stdout:
                log.write(line)
                try:
                    event = json.loads(line)
                except ValueError:
                    continue
                if event.get('event') == 'progress':
                    write_status(directory, progress=max(0, min(1, float(event['fraction']))))
                elif event.get('event') == 'stage':
                    changes = {}
                    if event.get('stage'): changes['stage'] = STAGES.get(event['stage'], event['stage'])
                    if 'estimatedRemainingSeconds' in event: changes['estimatedRemainingSeconds'] = event['estimatedRemainingSeconds']
                    if changes: write_status(directory, **changes)
                elif event.get('event') == 'error':
                    native_error = event.get('message')
                elif event.get('event') == 'crop':
                    write_status(directory, crop=event)
                elif event.get('event') == 'configuration':
                    write_status(directory, reconstructionConfiguration=event)
            code = process.wait()
            if timed_out.is_set(): raise RuntimeError('Tempo máximo de 2 horas excedido. Tente menos quadros ou detalhe reduzido.')
            if code: raise RuntimeError(native_error or f'Object Capture encerrou com código {code}. Confira os logs.')
        if not destination.is_file() or destination.stat().st_size < 1024:
            raise RuntimeError('O reconstrutor não produziu um USDZ válido.')
        write_status(directory, status='completed', stage='finished', progress=1, resultName='head.usdz', resultBytes=destination.stat().st_size, durationSeconds=time.time()-started)
    except Exception as error:
        with (directory / 'pipeline.log').open('a') as log: log.write(f'\nERRO: {error}\n')
        write_status(directory, status='failed', stage='failed', error=str(error), durationSeconds=time.time()-started)
    finally:
        if timer: timer.cancel()
        if process:
            with ACTIVE_LOCK: ACTIVE.discard(process)
        if process and process.poll() is None: process.kill(); process.wait()
